import React from 'react';
import { FaTrophy, FaCertificate, FaMedal, FaAward, FaGraduationCap, FaCode } from 'react-icons/fa';

const achievementsData = {
    certifications: [
        // {
        //     id: 1,
        //     title: "AWS Certified Solutions Architect",
        //     issuer: "Amazon Web Services",
        //     date: "2024",
        //     credentialId: "AWS-CSA-2024-001",
        //     level: "Associate",
        //     status: "Active"
        // },
        // {
        //     id: 2,
        //     title: "MongoDB Certified Developer",
        //     issuer: "MongoDB University",
        //     date: "2023",
        //     credentialId: "MONGO-DEV-2023-456",

        //     level: "Professional",
        //     status: "Active"
        // },
        // {
        //     id: 3,
        //     title: "React Developer Certification",
        //     issuer: "Meta (Facebook)",
        //     date: "2023",
        //     credentialId: "META-REACT-2023-789",
        //     level: "Professional",
        //     status: "Active"
        // },
        // {
        //     id: 4,
        //     title: "Google Cloud Platform Fundamentals",
        //     issuer: "Google Cloud",
        //     date: "2023",
        //     credentialId: "GCP-FUND-2023-012",
        //     level: "Fundamentals",
        //     status: "Active"
        // }
    ],
    awards: [
        {
            id: 1,
            title: "Award of Merit",
            event: "Enterprise Architecture Competition By Open Group",
            date: "01 August 2025",
            description: "Received an award for developing the architecture of a corporate medical society — a forward-thinking model that represents the future of medical retail and transportation.",
            icon: FaTrophy,
            category: "Competition"
        },
        {
            id: 2,
            title: "Second Price Winner",
            event: "Tech Tank Hackthon By RVCE,Bengaluru",
            date: "Jan 2025",
            description:"Received second prize for developing a solution to help fishermen avoid unintentionally crossing maritime borders.",
            icon: FaTrophy,
            category: "Competition"
        },
        {
            id: 3,
            title: "Participated in 48 hours Hackathon",
            event: "EduAIthon By RVCE,Bengaluru",
            date: "2025",
            description: "Built a platform enabling students, entrepreneurs, and mentors to communicate and collaborate, featuring AI-based mentorship support.",
            icon: FaMedal,
            category: "Academic"
        },
        {
            id: 4,
            title: "Open Source Contributor",
            event: "GitHub",
            date: "2022-Present",
            description: "Active contributor to popular React and Node.js libraries with 100+ stars",
            icon: FaCode,
            category: "Community"
        }
    ],
    
};

function Achievements() {
    return (
        <section id="achievements" className="py-20 px-6 sm:px-8 lg:px-12 bg-gradient-to-br from-[#1a1f26] to-[#20262E]">
            <div className="max-w-7xl mx-auto">
                {/* Section Header */}
                <div className="text-center mb-16">
                    <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
                        Achievements & <span className="text-[#6699CC]">Certifications</span>
                    </h2>
                    <div className="w-24 h-1 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
                    <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
                        Recognition, certifications, and milestones that mark my professional journey
                    </p>
                </div>

                {/* Key Achievements */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-16">
                    {achievementsData.achievements.map((achievement) => (
                        <div key={achievement.id} className="bg-gray-800/50 rounded-xl p-6 border border-gray-700/50 text-center hover:border-[#6699CC]/50 transition-all duration-300 group">
                            <div className="text-4xl mb-4">{achievement.icon}</div>
                            <h3 className="text-3xl font-bold text-[#6699CC] mb-2">{achievement.metric}</h3>
                            <h4 className="text-white font-semibold mb-2">{achievement.title}</h4>
                            <p className="text-gray-400 text-sm">{achievement.description}</p>
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                    {/* Certifications */}
                    <div>
                        <h3 className="text-3xl font-bold text-white mb-8 flex items-center">
                            <FaCertificate className="text-[#6699CC] mr-3" />
                            Certifications
                        </h3>
                        <div className="space-y-6">
                            {achievementsData.certifications.map((cert) => (
                                <div key={cert.id} className="bg-gray-800/50 rounded-xl p-6 border border-gray-700/50 hover:border-[#6699CC]/50 transition-all duration-300">
                                    <div className="flex items-start space-x-4">
                                        <div className="text-3xl">{cert.icon}</div>
                                        <div className="flex-1">
                                            <div className="flex items-start justify-between mb-2">
                                                <h4 className="text-lg font-semibold text-white">{cert.title}</h4>
                                                <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                                                    cert.status === 'Active' ? 'bg-green-500/20 text-green-400' : 'bg-gray-500/20 text-gray-400'
                                                }`}>
                                                    {cert.status}
                                                </span>
                                            </div>
                                            <p className="text-[#6699CC] font-medium mb-1">{cert.issuer}</p>
                                            <p className="text-gray-400 text-sm mb-2">Issued: {cert.date} • Level: {cert.level}</p>
                                            <p className="text-gray-500 text-xs">Credential ID: {cert.credentialId}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Awards & Recognition */}
                    <div>
                        <h3 className="text-3xl font-bold text-white mb-8 flex items-center">
                            <FaTrophy className="text-[#6699CC] mr-3" />
                            Awards & Recognition
                        </h3>
                        <div className="space-y-6">
                            {achievementsData.awards.map((award) => (
                                <div key={award.id} className="bg-gray-800/50 rounded-xl p-6 border border-gray-700/50 hover:border-[#6699CC]/50 transition-all duration-300">
                                    <div className="flex items-start space-x-4">
                                        <div className="w-12 h-12 bg-[#6699CC]/20 rounded-full flex items-center justify-center">
                                            <award.icon className="text-[#6699CC] text-xl" />
                                        </div>
                                        <div className="flex-1">
                                            <div className="flex items-start justify-between mb-2">
                                                <h4 className="text-lg font-semibold text-white">{award.title}</h4>
                                                <span className="px-3 py-1 bg-[#6699CC]/20 text-[#6699CC] rounded-full text-xs font-medium">
                                                    {award.category}
                                                </span>
                                            </div>
                                            <p className="text-[#6699CC] font-medium mb-1">{award.event}</p>
                                            <p className="text-gray-400 text-sm mb-2">{award.date}</p>
                                            <p className="text-gray-300 text-sm">{award.description}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Professional Stats */}
                <div className="mt-16 bg-gradient-to-r from-gray-800/50 to-gray-700/50 rounded-2xl p-8 border border-gray-700/50">
                    <h3 className="text-2xl font-bold text-white mb-8 text-center">
                        Professional Impact
                    </h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-8 text-center">
                        <div>
                            <FaCode className="text-[#6699CC] text-3xl mx-auto mb-3" />
                            <h4 className="text-3xl font-bold text-white">100K+</h4>
                            <p className="text-gray-300">Lines of Code</p>
                        </div>
                        <div>
                            <FaMedal className="text-[#6699CC] text-3xl mx-auto mb-3" />
                            <h4 className="text-3xl font-bold text-white">5</h4>
                            <p className="text-gray-300">Awards Won</p>
                        </div>
                        <div>
                            <FaCertificate className="text-[#6699CC] text-3xl mx-auto mb-3" />
                            <h4 className="text-3xl font-bold text-white">8</h4>
                            <p className="text-gray-300">Certifications</p>
                        </div>
                        <div>
                            <FaTrophy className="text-[#6699CC] text-3xl mx-auto mb-3" />
                            <h4 className="text-3xl font-bold text-white">100%</h4>
                            <p className="text-gray-300">Project Success</p>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
}

export default Achievements;
